package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import org.apache.commons.cli.CommandLine;
import org.apache.commons.cli.Option;
import org.apache.commons.cli.Options;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class CommandLine_hasOption_TriageGen2Test {

    private CommandLine commandLine;
    private Options options;

    @Before
    public void setUp() {
        options = new Options();
    }

    @Test
    public void testHasOption_WithExistingOption_ShouldReturnTrue() {
        Option option = Option.builder("f").hasArg().desc("file").build();
        options.addOption(option);
        commandLine = new CommandLine(options).parse(new String[]{"-f", "file.txt"});
        assertTrue(commandLine.hasOption("f"));
    }

    @Test
    public void testHasOption_WithNonExistingOption_ShouldReturnFalse() {
        commandLine = new CommandLine(options);
        assertFalse(commandLine.hasOption("f"));
    }

    @Test
    public void testHasOption_WithEmptyOption_ShouldReturnFalse() {
        commandLine = new CommandLine(options);
        assertFalse(commandLine.hasOption(""));
    }

    @Test
    public void testHasOption_WithNullOption_ShouldReturnFalse() {
        commandLine = new CommandLine(options);
        assertFalse(commandLine.hasOption(null));
    }

    @Test
    public void testHasOption_WithMultipleOptions_ShouldReturnTrueForExisting() {
        Option opt1 = Option.builder("f").hasArg().desc("file").build();
        Option opt2 = Option.builder("v").build();
        options.addOption(opt1);
        options.addOption(opt2);
        commandLine = new CommandLine(options).parse(new String[]{"-f", "file.txt", "-v"});
        assertTrue(commandLine.hasOption("f"));
        assertTrue(commandLine.hasOption("v"));
    }

    @Test
    public void testHasOption_WithMultipleOptions_ShouldReturnFalseForNonExisting() {
        Option opt1 = Option.builder("f").hasArg().desc("file").build();
        Option opt2 = Option.builder("v").build();
        options.addOption(opt1);
        options.addOption(opt2);
        commandLine = new CommandLine(options).parse(new String[]{"-f", "file.txt"});
        assertFalse(commandLine.hasOption("v"));
    }

    @Test
    public void testHasOption_WithNoOptionsProvided_ShouldReturnFalse() {
        commandLine = new CommandLine(options);
        assertFalse(commandLine.hasOption("f"));
    }
}
